fn find_jsx_variable<'a>(var_name: &str, body: &'a BlockStmt) -> Option<&'a Expr> {
    let mut found_node: Option<&Expr> = None;

    'outer: for statement in &body.stmts {
        if let Stmt::Decl(Decl::Var(var_decl)) = statement {
            for declarator in &var_decl.decls {
                if let Pat::Ident(ident) = &declarator.name {
                    if ident.id.sym.as_ref() == var_name {
                        if let Some(init) = &declarator.init {
                            // Direct JSX
                            if matches!(init.as_ref(), Expr::JSXElement(_) | Expr::JSXFragment(_)) {
                                found_node = Some(init.as_ref());
                                break;
                            }
                            // Logical expression: loading && <div>
                            if let Expr::Bin(bin_expr) = init.as_ref() {
                                if matches!(bin_expr.op, BinaryOp::LogicalAnd | BinaryOp::LogicalOr) {
                                    if matches!(bin_expr.right.as_ref(), Expr::JSXElement(_) | Expr::JSXFragment(_)) {
                                        found_node = Some(init.as_ref());
                                        break;
                                    }
                                }
                            }
                            // Parenthesized expression
                            if let Expr::Paren(paren_expr) = init.as_ref() {
                                let inner = &paren_expr.expr;
                                if matches!(inner.as_ref(), Expr::JSXElement(_) | Expr::JSXFragment(_)) {
                                    found_node = Some(inner.as_ref());
                                    break;
                                }
                                if matches!(inner.as_ref(), Expr::Bin(BinExpr { op: BinaryOp::LogicalAnd | BinaryOp::LogicalOr, .. })) {
                                    found_node = Some(inner.as_ref());
                                    break;
                                }
                            }
                        }
                    }
                }
            }
        }
        if found_node.is_some() { break 'outer; }
    }

    found_node
}
